#!/usr/bin/env node
/**
 * Concatenates the -v1 Supabase patches, in the required order, into one file you can paste
 * into the SQL editor once: supabase/apply-all-v1.sql. Every patch is safe to re-run.
 *
 *   node scripts/build-v1-patch-bundle.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.join(path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..'), 'supabase');
const ORDER = [
  'patch-prereq-v1.sql',
  'patch-saved-searches-v1.sql',
  'patch-listing-integrity-v1.sql',
  'patch-seller-tools-v1.sql',
  'patch-privacy-v1.sql',
  'patch-freshness-v1.sql',
  'patch-hardening-v1.sql',
  'patch-telegram-auth-v1.sql',
  'patch-alerts-v1.sql',
];

const parts = ORDER.map((name) => `-- >>>>>>>>>>>>>>>> ${name} <<<<<<<<<<<<<<<<\n${fs.readFileSync(path.join(dir, name), 'utf8').trim()}\n`);
const header = `-- GENERATED by scripts/build-v1-patch-bundle.mjs — do not edit by hand.
-- All Reyeltor-uz -v1 patches in the required order. Run AFTER schema.sql, storage-setup.sql
-- and any older patch-*.sql. Safe to re-run. Take a database backup first.
begin;
`;
fs.writeFileSync(path.join(dir, 'apply-all-v1.sql'), `${header}\n${parts.join('\n')}\ncommit;\n`);
console.log(`Wrote supabase/apply-all-v1.sql (${ORDER.length} patches)`);
